-- Initial schema for KarmaDice

-- Rolls: one row per completed roll (server-side truth for idempotency & auditing)
CREATE TABLE rolls (
                id               BIGSERIAL PRIMARY KEY,
    -- Public identifier generated by the app (UUID v4 recommended)
                public_id        UUID NOT NULL,
                die              TEXT NOT NULL CHECK (die IN ('d6','d20','d100')),
                kappa            DOUBLE PRECISION NOT NULL,
                seed             TEXT,
                idempotency_key  TEXT UNIQUE,
    -- Minimal computed summary (details transcript lives in S3/MinIO)
                face             INTEGER NOT NULL,
                ev               DOUBLE PRECISION NOT NULL,
                alpha            DOUBLE PRECISION NOT NULL,
                kl               DOUBLE PRECISION NOT NULL,
                created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Transcript metadata: points to the S3/MinIO object containing the full blob
CREATE TABLE transcripts_meta (
                id          BIGSERIAL PRIMARY KEY,
                roll_id     BIGINT NOT NULL REFERENCES rolls(id) ON DELETE CASCADE,
                s3_key      TEXT NOT NULL UNIQUE,
                sha256      BYTEA,
                size_bytes  BIGINT,
                created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Event log: lightweight audit trail (optional, nice for observability)
CREATE TABLE events (
                id          BIGSERIAL PRIMARY KEY,
                roll_id     BIGINT REFERENCES rolls(id) ON DELETE SET NULL,
                event_type  TEXT NOT NULL,
                payload     JSONB,
                created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Helpful indexes
CREATE INDEX idx_rolls_created_at   ON rolls(created_at DESC);
CREATE INDEX idx_events_roll_id     ON events(roll_id, created_at DESC);
